{"path":"/workspace/server.js","content":"import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";
import { createStore } from "./lib/store.js";

const root = dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT) || 3000;
const dataFile = process.env.BOOKS_FILE || join(root, "data", "books.json");
const store = createStore(dataFile);

function send(res, status, body, type = "text/html; charset=utf-8") {
  res.writeHead(status, { "content-type": type });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

async function readForm(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (method === "GET" && path === "/styles.css") {
      const css = await readFile(join(root, "public", "styles.css"), "utf8");
      return send(res, 200, css, "text/css; charset=utf-8");
    }

    if (method === "GET" && path === "/") {
      const books = await store.list();
      return send(res, 200, homePage(books));
    }

    if (method === "POST" && path === "/books") {
      const form = await readForm(req);
      try {
        const book = await store.add({
          title: form.get("title"),
          author: form.get("author"),
          notes: form.get("notes"),
        });
        return redirect(res, `/books/${book.id}`);
      } catch (error) {
        if (error && error.code === "VALIDATION") return redirect(res, "/");
        throw error;
      }
    }

    const detail = path.match(/^\/books\/([^/]+)$/);
    if (method === "GET" && detail) {
      const book = await store.get(decodeURIComponent(detail[1]));
      if (!book) return send(res, 404, notFoundPage());
      return send(res, 200, bookPage(book));
    }

    const finish = path.match(/^\/books\/([^/]+)\/finish$/);
    if (method === "POST" && finish) {
      const id = decodeURIComponent(finish[1]);
      const book = await store.finish(id);
      if (!book) return send(res, 404, notFoundPage());
      return redirect(res, `/books/${id}`);
    }

    return send(res, 404, notFoundPage());
  } catch (error) {
    console.error(error);
    return send(res, 500, "Something went wrong.", "text/plain; charset=utf-8");
  }
});

server.listen(port, () => {
  console.log(`Reading list at http://localhost:${port}`);
});
"}

{"path":"/workspace/lib/store.test.js","content":"import { mkdtemp, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createStore } from "./store.js";

const files = [];

afterEach(async () => {
  files.length = 0;
});

async function tempStore() {
  const dir = await mkdtemp(join(tmpdir(), "books-"));
  const file = join(dir, "books.json");
  files.push(file);
  return createStore(file);
}

describe("book store", () => {
  it("starts empty when the file does not exist", async () => {
    const store = await tempStore();
    expect(await store.list()).toEqual([]);
  });

  it("adds a reading book and reloads it from the JSON file", async () => {
    const store = await tempStore();
    const added = await store.add({
      title: " The Left Hand of Darkness ",
      author: "Ursula K. Le Guin",
      notes: "Slow start, then excellent.",
    });

    expect(added.status).toBe("reading");
    expect(added.title).toBe("The Left Hand of Darkness");

    const reloaded = createStore(store.filePath);
    const books = await reloaded.list();
    expect(books).toHaveLength(1);
    expect(books[0].id).toBe(added.id);
    expect(books[0].author).toBe("Ursula K. Le Guin");

    const raw = JSON.parse(await readFile(store.filePath, "utf8"));
    expect(raw.books[0].notes).toBe("Slow start, then excellent.");
  });

  it("rejects a blank title", async () => {
    const store = await tempStore();
    await expect(store.add({ title: "   ", author: "X" })).rejects.toMatchObject({
      code: "VALIDATION",
    });
    expect(await store.list()).toEqual([]);
  });

  it("marks a book finished and keeps that after reload", async () => {
    const store = await tempStore();
    const added = await store.add({ title: "Kindred", author: "Octavia Butler" });
    const finished = await store.finish(added.id);
    expect(finished.status).toBe("finished");
    expect(finished.finishedAt).toBeTruthy();

    const again = await store.finish(added.id);
    expect(again.finishedAt).toBe(finished.finishedAt);

    const reloaded = createStore(store.filePath);
    expect((await reloaded.get(added.id)).status).toBe("finished");
    expect(await store.finish("missing")).toBeNull();
  });
});
"}

