import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createStore } from "./store.js";

const files = [];

afterEach(async () => {
  files.length = 0;
});

async function tempStore() {
  const dir = await mkdtemp(join(tmpdir(), "books-"));
  const file = join(dir, "books.json");
  files.push(file);
  return createStore(file);
}

describe("book store", () => {
  it("starts empty when the file does not exist", async () => {
    const store = await tempStore();
    expect(await store.list()).toEqual([]);
  });

  it("adds a reading book and reloads it from the JSON file", async () => {
    const store = await tempStore();
    const added = await store.add({
      title: " The Left Hand of Darkness ",
      author: "Ursula K. Le Guin",
      notes: "Slow start, then excellent.",
    });

    expect(added.status).toBe("reading");
    expect(added.title).toBe("The Left Hand of Darkness");

    const reloaded = createStore(store.filePath);
    const books = await reloaded.list();
    expect(books).toHaveLength(1);
    expect(books[0].id).toBe(added.id);
    expect(books[0].author).toBe("Ursula K. Le Guin");

    const raw = JSON.parse(await readFile(store.filePath, "utf8"));
    expect(raw.books[0].notes).toBe("Slow start, then excellent.");
  });

  it("rejects a blank title", async () => {
    const store = await tempStore();
    await expect(store.add({ title: "   ", author: "X" })).rejects.toMatchObject({
      code: "VALIDATION",
    });
    expect(await store.list()).toEqual([]);
  });

  it("marks a book finished and keeps that after reload", async () => {
    const store = await tempStore();
    const added = await store.add({ title: "Kindred", author: "Octavia Butler" });
    const finished = await store.finish(added.id);
    expect(finished.status).toBe("finished");
    expect(finished.finishedAt).toBeTruthy();

    const again = await store.finish(added.id);
    expect(again.finishedAt).toBe(finished.finishedAt);

    const reloaded = createStore(store.filePath);
    expect((await reloaded.get(added.id)).status).toBe("finished");
    expect(await store.finish("missing")).toBeNull();
  });
});
